using BetterArc.Chart;
using BetterArc.Chart.Events;

namespace BetterArc.Gameplay;

public class GameplayService
{
    private readonly List<Chart.TimingGroup> _timingGroups = new();

    public AffChart? Chart { get; private set; }
    public int CurrentTiming { get; set; }
    public float DropRate { get; set; } = 1f;

    public void LoadChart(string affText)
    {
        Chart = AffParser.Parse(affText);
        _timingGroups.Clear();

        foreach (var affTg in Chart.TimingGroups)
        {
            var tg = new Chart.TimingGroup();
            foreach (var t in affTg.Timings)
                tg.AddTiming(t);
            tg.RecalculateFloorPositions();
            _timingGroups.Add(tg);
        }

        Values.BaseBpm = Chart.TimingGroups[0].Timings.Count > 0
            ? Chart.TimingGroups[0].Timings[0].Bpm
            : 100f;
        Values.TimingPointDensity = Chart.TimingPointDensity;
    }

    public double GetFloorPosition(int timingGroup, int timing)
    {
        if (timingGroup >= _timingGroups.Count) return 0;
        return _timingGroups[timingGroup].GetFloorPosition(timing);
    }

    public float GetNoteZ(int timingGroup, int noteTiming)
    {
        double noteFp = GetFloorPosition(timingGroup, noteTiming);
        double currentFp = GetFloorPosition(timingGroup, CurrentTiming);
        double relativeFp = noteFp - currentFp;
        return ArcFormula.FloorPositionToZ(relativeFp, DropRate);
    }

    public IEnumerable<Tap> GetVisibleTaps(int timingGroup)
    {
        if (Chart == null || timingGroup >= Chart.TimingGroups.Count) yield break;
        foreach (var tap in Chart.TimingGroups[timingGroup].Taps)
        {
            float z = GetNoteZ(timingGroup, tap.Timing);
            if (ArcFormula.WithinRenderRange(z))
                yield return tap;
        }
    }

    public IEnumerable<Hold> GetVisibleHolds(int timingGroup)
    {
        if (Chart == null || timingGroup >= Chart.TimingGroups.Count) yield break;
        foreach (var hold in Chart.TimingGroups[timingGroup].Holds)
        {
            float zStart = GetNoteZ(timingGroup, hold.Timing);
            float zEnd = GetNoteZ(timingGroup, hold.EndTiming);
            if (ArcFormula.WithinRenderRange(zStart) || ArcFormula.WithinRenderRange(zEnd)
                || (zStart > 0 && zEnd < 0))
                yield return hold;
        }
    }

    public IEnumerable<Arc> GetVisibleArcs(int timingGroup)
    {
        if (Chart == null || timingGroup >= Chart.TimingGroups.Count) yield break;
        foreach (var arc in Chart.TimingGroups[timingGroup].Arcs)
        {
            float zStart = GetNoteZ(timingGroup, arc.Timing);
            float zEnd = GetNoteZ(timingGroup, arc.EndTiming);
            if (ArcFormula.WithinRenderRange(zStart) || ArcFormula.WithinRenderRange(zEnd)
                || (zStart > 0 && zEnd < 0))
                yield return arc;
        }
    }
}

