83	    {
84	        float o = 1 - t;
85	        return (MathF.Pow(o, 3) * start)
86	             + (3 * MathF.Pow(o, 2) * t * start)
87	             + (3 * o * MathF.Pow(t, 2) * end)
88	             + (MathF.Pow(t, 3) * end);
