97	                return S(start, end, t);
98	            case ArcLineType.B:
99	                return B(start, end, t);
100	            case ArcLineType.Si:
101	            case ArcLineType.SiSi:
102	            case ArcLineType.SiSo:
103	                return I(start, end, t);
104	            case ArcLineType.So:
