142	    public static List<int> CalculateLongNoteJudgeTimings(int from, int to, float bpm)
143	    {
144	        List<int> result = new List<int>();
145	
146	        int u = 0;
147	        bpm = MathF.Abs(bpm);
148	        float interval = 60000f / bpm / (bpm >= 255 ? 1 : 2) / Values.TimingPointDensity;
149	        int total = (int)((to - from) / interval);
150	        if ((u ^ 1) >= total)
151	        {
152	            result.Add((int)(from + ((to - from) * 0.5f)));
153	            return result;
154	        }
155	
156	        int n = u ^ 1;
157	        while (true)
158	        {
159	            int t = (int)(from + (n * interval));
160	            if (t < to)
161	            {
162	                result.Add(t);
163	            }
164	
165	            if (total == ++n)
166	            {
167	                break;
168	            }
169	        }
170	
171	        return result;
172	    }
