185	    {
186	        if (z <= 0)
187	        {
188	            return MathF.Abs(thickness + (thickness * 3 * -z / Values.TrackLengthForward));
189	        }
190	
191	        return MathF.Abs(thickness + (thickness * 3 * z / Values.TrackLengthBackward));
192	    }
193	
194	    public static float CalculateFadeOutAlpha(float z)
195	    {
196	        if (z <= 0)
197	        {
198	            return Math.Clamp((Values.TrackLengthForward + z) / Values.NoteFadeOutLength, 0, 1);
199	        }
200	
201	        return Math.Clamp((Values.TrackLengthBackward - z) / Values.NoteFadeOutLength, 0, 1);
202	    }
