1	using System.Text;
2	using Microsoft.Xna.Framework;
3	using Microsoft.Xna.Framework.Graphics;
4	using BetterArc.Gameplay;
5	using BetterArc.Render;
6	
7	namespace BetterArc.Tests.Visual;
8	
9	public abstract class VisualTestBase
10	{
11	    protected abstract string ChartName { get; }
12	    protected abstract string ChartPath { get; }
13	    protected abstract float SsimThreshold { get; }
14	
15	    protected int Width => 1280;
16	    protected int Height => 720;
17	
18	    protected void RunVisualComparison()
19	    {
20	        string? refDir = FindReferenceDir();
21	        if (refDir == null || !Directory.Exists(refDir))
22	        {
23	            return;
24	        }
25	
26	        var timePoints = ScanReferenceFrames(refDir);
27	        if (timePoints.Count == 0)
28	        {
29	            return;
30	        }
31	
32	        string chartFullPath = FindChartFile();
33	        string chartText = File.ReadAllText(chartFullPath);
34	        string outputDir = GetOutputDir();
35	        Directory.CreateDirectory(outputDir);
36	
37	        var renderGame = new RenderBatchGame(
38	            Width, Height, chartText, timePoints, outputDir);
39	
40	        try
41	        {
42	            renderGame.Run();
43	        }
44	        catch (NoSuitableGraphicsDeviceException)
45	        {
46	            return;
47	        }
48	
49	        var results = new List<FrameResult>();
50	        foreach (var (timeMs, refPath) in timePoints)
51	        {
52	            string actualPath = Path.Combine(outputDir, $"actual_t{FormatTime(timeMs)}.png");
53	            if (!File.Exists(actualPath)) continue;
54	
55	            string diffPath = Path.Combine(outputDir, $"diff_t{FormatTime(timeMs)}.png");
56	            float ssim = ImageComparer.GenerateDiff(refPath, actualPath, diffPath);
57	            results.Add(new FrameResult(timeMs, ssim, diffPath));
58	        }
59	
60	        string reportPath = Path.Combine(outputDir, "report.txt");
61	        WriteReport(reportPath, results);
62	
63	        var failed = results.Where(r => r.Ssim < SsimThreshold).ToList();
64	        if (failed.Count > 0)
65	        {
66	            var worst = failed.OrderBy(r => r.Ssim).First();
67	            Assert.Fail(
68	                $"L2 visual comparison failed: {failed.Count}/{results.Count} frames below threshold ({SsimThreshold:F2}).\n" +
69	                $"Worst: t{FormatTime(worst.TimeMs)} SSIM={worst.Ssim:F4}\n" +
70	                $"Report: {reportPath}");
71	        }
72	    }
73	
74	    private string? FindReferenceDir()
75	    {
76	        string[] candidates =
77	        {
78	            Path.Combine(AppContext.BaseDirectory, "TestData", "L2", ChartName),
79	            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "TestData", "L2", ChartName),
80	        };
81	        foreach (var c in candidates)
82	        {
83	            string resolved = Path.GetFullPath(c);
84	            if (Directory.Exists(resolved)) return resolved;
85	        }
86	        return null;
87	    }
88	
89	    private string FindChartFile()
90	    {
91	        string[] candidates =
92	        {
93	            Path.Combine(AppContext.BaseDirectory, ChartPath),
94	            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", ChartPath),
95	        };
96	        foreach (var c in candidates)
97	        {
98	            string resolved = Path.GetFullPath(c);
99	            if (File.Exists(resolved)) return resolved;
100	        }
101	        throw new FileNotFoundException($"Chart file not found: {ChartPath}");
102	    }
103	
104	    internal static List<(int timeMs, string path)> ScanReferenceFrames(string dir)
105	    {
106	        var results = new List<(int, string)>();
107	
108	        foreach (var file in Directory.GetFiles(dir, "t*.png"))
109	        {
110	            string name = Path.GetFileNameWithoutExtension(file);
111	            if (TryParseTime(name, out int timeMs))
112	                results.Add((timeMs, file));
113	        }
114	
115	        results.Sort((a, b) => a.Item1.CompareTo(b.Item1));
116	        return results;
117	    }
118	
119	    internal static bool TryParseTime(string name, out int timeMs)
120	    {
121	        timeMs = 0;
122	        if (name.Length < 2 || name[0] != 't') return false;
123	        return int.TryParse(name.Substring(1), out timeMs);
124	    }
125	
126	    internal static string FormatTime(int timeMs)
127	    {
128	        if (timeMs < 0)
129	            return $"-{(-timeMs):D5}";
130	        return $"{timeMs:D5}";
131	    }
132	
133	    private string GetOutputDir()
134	    {
135	        string baseDir = Path.Combine(
136	            AppContext.BaseDirectory, "..", "..", "..", "..", "TestResults", "L2", ChartName);
137	        return Path.GetFullPath(baseDir);
138	    }
139	
140	    private void WriteReport(string path, List<FrameResult> results)
141	    {
142	        var sb = new StringBuilder();
143	        sb.AppendLine($"Chart: {ChartName}");
144	        sb.AppendLine($"Threshold: {SsimThreshold:F2}");
145	
146	        int passed = results.Count(r => r.Ssim >= SsimThreshold);
147	        int failed = results.Count - passed;
148	        sb.AppendLine($"Frames: {results.Count} total, {passed} passed, {failed} failed");
149	        sb.AppendLine();
150	
151	        var failedFrames = results.Where(r => r.Ssim < SsimThreshold)
152	            .OrderBy(r => r.Ssim).ToList();
153	        if (failedFrames.Count > 0)
154	        {
155	            sb.AppendLine("FAILED FRAMES:");
156	            foreach (var f in failedFrames)
157	                sb.AppendLine($"  t{FormatTime(f.TimeMs)}  SSIM={f.Ssim:F4}  diff: {Path.GetFileName(f.DiffPath)}");
158	            sb.AppendLine();
159	        }
160	
161	        var worstPassed = results.Where(r => r.Ssim >= SsimThreshold)
162	            .OrderBy(r => r.Ssim).Take(5).ToList();
163	        if (worstPassed.Count > 0)
164	        {
165	            sb.AppendLine("PASSED FRAMES (worst 5):");
166	            foreach (var f in worstPassed)
167	                sb.AppendLine($"  t{FormatTime(f.TimeMs)}  SSIM={f.Ssim:F4}");
168	        }
169	
170	        File.WriteAllText(path, sb.ToString());
171	    }
172	
173	    private record FrameResult(int TimeMs, float Ssim, string DiffPath);
174	}
175	
176	internal class RenderBatchGame : Game
177	{
178	    private readonly GraphicsDeviceManager _graphics;
179	    private readonly string _chartText;
180	    private readonly List<(int timeMs, string refPath)> _timePoints;
181	    private readonly string _outputDir;
182	
183	    private CameraService? _camera;
184	    private TextureService? _textures;
185	    private TrackRenderer? _track;
186	    private NoteRenderer? _notes;
187	    private GameplayService? _gameplay;
188	    private int _frameIndex;
189	
190	    public RenderBatchGame(
191	        int width, int height, string chartText,
192	        List<(int timeMs, string refPath)> timePoints, string outputDir)
193	    {
194	        _chartText = chartText;
195	        _timePoints = timePoints;
196	        _outputDir = outputDir;
197	
198	        _graphics = new GraphicsDeviceManager(this)
199	        {
200	            PreferredBackBufferWidth = width,
201	            PreferredBackBufferHeight = height,
202	            GraphicsProfile = GraphicsProfile.HiDef,
203	        };
204	
205	        IsMouseVisible = false;
206	        IsFixedTimeStep = false;
207	    }
208	
209	    protected override void Initialize()
210	    {
211	        _camera = new CameraService();
212	        _textures = new TextureService();
213	        _textures.Initialize(GraphicsDevice);
214	        _track = new TrackRenderer(GraphicsDevice);
215	        _notes = new NoteRenderer(GraphicsDevice);
216	        _gameplay = new GameplayService();
217	        _gameplay.LoadChart(_chartText);
218	
219	        base.Initialize();
220	    }
221	
222	    protected override void Draw(GameTime gameTime)
223	    {
224	        if (_frameIndex >= _timePoints.Count)
225	        {
226	            Exit();
227	            return;
228	        }
229	
230	        var (timeMs, _) = _timePoints[_frameIndex];
231	        _gameplay!.CurrentTiming = timeMs;
232	
233	        string filename = $"actual_t{VisualTestBase.FormatTime(timeMs)}.png";
234	        string outputPath = Path.Combine(_outputDir, filename);
235	
236	        ScreenshotService.CaptureToFile(
237	            GraphicsDevice, _camera!, _textures!, _track!, _notes!, _gameplay!,
238	            _graphics.PreferredBackBufferWidth, _graphics.PreferredBackBufferHeight,
239	            outputPath);
240	
241	        _frameIndex++;
242	
243	        if (_frameIndex >= _timePoints.Count)
244	            Exit();
