using System.Diagnostics;
using System.Text;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using BetterArc.Gameplay;
using BetterArc.Render;
using Xunit.Abstractions;

namespace BetterArc.Tests.Visual;

public abstract class VisualTestBase
{
    protected abstract string ChartName { get; }
    protected abstract string ChartPath { get; }
    protected abstract float SsimThreshold { get; }
    protected ITestOutputHelper? Output { get; init; }

    protected int Width => 1280;
    protected int Height => 720;

    protected void RunVisualComparison()
    {
        string? refDir = FindReferenceDir();
        if (refDir == null || !Directory.Exists(refDir))
        {
            return;
        }

        var timePoints = ScanReferenceFrames(refDir);
        if (timePoints.Count == 0)
        {
            return;
        }

        string chartFullPath = FindChartFile();
        string chartText = File.ReadAllText(chartFullPath);
        string outputDir = GetOutputDir();
        Directory.CreateDirectory(outputDir);

        var renderGame = new RenderBatchGame(
            Width, Height, chartText, timePoints, outputDir);

        try
        {
            renderGame.Run();
        }
        catch (NoSuitableGraphicsDeviceException)
        {
            return;
        }

        var frameInputs = new List<(int timeMs, string refPath, string actualPath, string diffPath)>();
        foreach (var (timeMs, refPath) in timePoints)
        {
            string actualPath = Path.Combine(outputDir, $"actual_t{FormatTime(timeMs)}.png");
            if (!File.Exists(actualPath)) continue;
            string diffPath = Path.Combine(outputDir, $"diff_t{FormatTime(timeMs)}.png");
            frameInputs.Add((timeMs, refPath, actualPath, diffPath));
        }

        var results = new FrameResult[frameInputs.Count];
        Parallel.For(0, frameInputs.Count, i =>
        {
            var f = frameInputs[i];
            float ssim = ImageComparer.GenerateDiff(f.refPath, f.actualPath, f.diffPath);
            results[i] = new FrameResult(f.timeMs, ssim, f.diffPath);
        });
        var resultList = results.ToList();

        string reportPath = Path.Combine(outputDir, "report.txt");
        WriteReport(reportPath, resultList);

        var failed = resultList.Where(r => r.Ssim < SsimThreshold).ToList();
        if (failed.Count > 0)
        {
            var worst = failed.OrderBy(r => r.Ssim).First();
            Assert.Fail(
                $"L2 visual comparison failed: {failed.Count}/{resultList.Count} frames below threshold ({SsimThreshold:F2}).\n" +
                $"Worst: t{FormatTime(worst.TimeMs)} SSIM={worst.Ssim:F4}\n" +
                $"Report: {reportPath}");
        }
    }

    private string? FindReferenceDir()
    {
        string[] candidates =
        {
            Path.Combine(AppContext.BaseDirectory, "TestData", "L2", ChartName),
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "TestData", "L2", ChartName),
        };
        foreach (var c in candidates)
        {
            string resolved = Path.GetFullPath(c);
            if (Directory.Exists(resolved)) return resolved;
        }
        return null;
    }

    private string FindChartFile()
    {
        string[] candidates =
        {
            Path.Combine(AppContext.BaseDirectory, ChartPath),
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", ChartPath),
        };
        foreach (var c in candidates)
        {
            string resolved = Path.GetFullPath(c);
            if (File.Exists(resolved)) return resolved;
        }
        throw new FileNotFoundException($"Chart file not found: {ChartPath}");
    }

    internal static List<(int timeMs, string path)> ScanReferenceFrames(string dir)
    {
        var results = new List<(int, string)>();

        foreach (var file in Directory.GetFiles(dir, "t*.png"))
        {
            string name = Path.GetFileNameWithoutExtension(file);
            if (TryParseTime(name, out int timeMs))
                results.Add((timeMs, file));
        }

        results.Sort((a, b) => a.Item1.CompareTo(b.Item1));
        return results;
    }

    internal static bool TryParseTime(string name, out int timeMs)
    {
        timeMs = 0;
        if (name.Length < 2 || name[0] != 't') return false;
        return int.TryParse(name.Substring(1), out timeMs);
    }

    internal static string FormatTime(int timeMs)
    {
        if (timeMs < 0)
            return $"-{(-timeMs):D5}";
        return $"{timeMs:D5}";
    }

    private string GetOutputDir()
    {
        string baseDir = Path.Combine(
            AppContext.BaseDirectory, "..", "..", "..", "..", "TestResults", "L2", ChartName);
        return Path.GetFullPath(baseDir);
    }

    private void WriteReport(string path, List<FrameResult> results)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"Chart: {ChartName}");
        sb.AppendLine($"Threshold: {SsimThreshold:F2}");

        int passed = results.Count(r => r.Ssim >= SsimThreshold);
        int failed = results.Count - passed;
        sb.AppendLine($"Frames: {results.Count} total, {passed} passed, {failed} failed");
        sb.AppendLine();

        var failedFrames = results.Where(r => r.Ssim < SsimThreshold)
            .OrderBy(r => r.Ssim).ToList();
        if (failedFrames.Count > 0)
        {
            sb.AppendLine("FAILED FRAMES:");
            foreach (var f in failedFrames)
                sb.AppendLine($"  t{FormatTime(f.TimeMs)}  SSIM={f.Ssim:F4}  diff: {Path.GetFileName(f.DiffPath)}");
            sb.AppendLine();
        }

        var worstPassed = results.Where(r => r.Ssim >= SsimThreshold)
            .OrderBy(r => r.Ssim).Take(5).ToList();
        if (worstPassed.Count > 0)
        {
            sb.AppendLine("PASSED FRAMES (worst 5):");
            foreach (var f in worstPassed)
                sb.AppendLine($"  t{FormatTime(f.TimeMs)}  SSIM={f.Ssim:F4}");
        }

        File.WriteAllText(path, sb.ToString());
    }

    private record FrameResult(int TimeMs, float Ssim, string DiffPath);
}

internal class RenderBatchGame : Game
{
    private readonly GraphicsDeviceManager _graphics;
    private readonly string _chartText;
    private readonly List<(int timeMs, string refPath)> _timePoints;
    private readonly string _outputDir;

    private CameraService? _camera;
    private TextureService? _textures;
    private TrackRenderer? _track;
    private NoteRenderer? _notes;
    private GameplayService? _gameplay;
    private int _frameIndex;

    public RenderBatchGame(
        int width, int height, string chartText,
        List<(int timeMs, string refPath)> timePoints, string outputDir)
    {
        _chartText = chartText;
        _timePoints = timePoints;
        _outputDir = outputDir;

        _graphics = new GraphicsDeviceManager(this)
        {
            PreferredBackBufferWidth = width,
            PreferredBackBufferHeight = height,
            GraphicsProfile = GraphicsProfile.HiDef,
        };

        IsMouseVisible = false;
        IsFixedTimeStep = false;
    }

    protected override void Initialize()
    {
        _camera = new CameraService();
        _textures = new TextureService();
        _textures.Initialize(GraphicsDevice);
        _track = new TrackRenderer(GraphicsDevice);
        _notes = new NoteRenderer(GraphicsDevice);
        _gameplay = new GameplayService();
        _gameplay.LoadChart(_chartText);

        base.Initialize();
    }

    protected override void Draw(GameTime gameTime)
    {
        if (_frameIndex >= _timePoints.Count)
        {
            Exit();
            return;
        }

        var (timeMs, _) = _timePoints[_frameIndex];
        _gameplay!.CurrentTiming = timeMs;

        string filename = $"actual_t{VisualTestBase.FormatTime(timeMs)}.png";
        string outputPath = Path.Combine(_outputDir, filename);

        ScreenshotService.CaptureToFile(
            GraphicsDevice, _camera!, _textures!, _track!, _notes!, _gameplay!,
            _graphics.PreferredBackBufferWidth, _graphics.PreferredBackBufferHeight,
            outputPath);

        _frameIndex++;

        if (_frameIndex >= _timePoints.Count)
            Exit();

        base.Draw(gameTime);
    }
}

